<script setup>
import {s,callLabel,responseLabel} from './store';

const fields=[{key:'call_status',label:'Tình trạng gọi xác nhận'},{key:'position',label:'Chức vụ'},{key:'utm_content',label:'utm_content'},{key:'company',label:'Công ty'},{key:'department',label:'Phòng / nhóm'},{key:'staff_code',label:'Mã nhân viên'},{key:'assignee_name',label:'Người phụ trách'},{key:'contact_response',label:'Phản hồi'}];
</script><template><div class="grid-form"><label class="field">Tình trạng đăng ký<MSelect :model-value="s.rowFilters.registration_status?.[0]||'all'" aria-label="Tình trạng đăng ký" :options="[{value:'all',label:'Tất cả khách'},{value:'registered',label:'Đã đăng ký'},{value:'invited',label:'Đã mời — chưa đăng ký'}]" @update:model-value="s.rowFilters={...s.rowFilters,registration_status:$event==='all'?[]:[$event]}"/></label><label v-for="field in fields" :key="field.key" class="field">{{field.label}}<MCombobox v-model="s.rowFilters[field.key]" multiple :options="(s.rowOptions[field.key]||[]).map(value=>({value,label:field.key==='call_status'?callLabel(value):field.key==='contact_response'?responseLabel(value):value||'Chưa có dữ liệu'}))" placeholder="Tất cả" :aria-label="field.label"/></label><label class="field">Từ ngày submit<MDatePicker v-model="s.rowFrom"/></label><label class="field">Đến ngày submit<MDatePicker v-model="s.rowTo"/></label></div></template>